def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if m == 'D':
            my_d += 1

    opp_def_rate = opp_d / float(n)

    recent_start = n - 10 if n >= 10 else 0
    recent_opp_def = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    consec_opp_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_def += 1
        else:
            break

    consec_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_opp_c += 1
        else:
            break

    consec_my_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            consec_my_def += 1
        else:
            break

    forgiveness = 0
    retaliation = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i+1][1] == 'C':
                forgiveness += 1
            else:
                retaliation += 1

    if last_opp == 'D':
        if opp_def_rate > 0.5 or consec_opp_def >= 3:
            if n < 95 and consec_opp_def >= 3 and rng.random() < 0.2:
                return 'C'
            return 'D'
        if last_me == 'C':
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if consec_opp_def >= 2 and n < 95 and rng.random() < 0.3:
            return 'C'
        return 'D'

    if last_me == 'D':
        if opp_d == 0:
            return 'D'
        if forgiveness > retaliation:
            return 'D'
        if consec_my_def >= 3 and rng.random() < 0.5:
            return 'C'
        return 'D'

    if n < 5:
        return 'C'

    if consec_opp_c < 5:
        return 'C'

    if opp_d == 0:
        if my_d == 0:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        else:
            return 'D'

    if forgiveness > retaliation:
        if rng.random() < 0.4:
            return 'D'
        return 'C'
    elif forgiveness == retaliation:
        if rng.random() < 0.2:
            return 'D'
        return 'C'
    else:
        if rng.random() < 0.05:
            return 'D'
        return 'C'
